"use client"

import * as React from "react"
import { Maximize, Minus, Plus } from "lucide-react"

import { useElementWidth } from "@/hooks/use-element-width"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  MarkdownActionButtons,
  MarkdownActionsMenu,
} from "@/components/viewers/page-markdown/page-markdown-actions"
import { PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH } from "@/components/viewers/page-markdown/page-markdown-model"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export function PageMarkdownToolbar({
  currentPage,
  pageCount,
  mode,
  scale,
  text,
  fileName,
  onModeChange,
  onZoom,
  onFitWidth,
}: {
  currentPage: number
  pageCount: number
  mode: PageMarkdownViewMode
  scale: number
  text: string
  fileName: string
  onModeChange: (mode: PageMarkdownViewMode) => void
  onZoom: (factor: number) => void
  onFitWidth: () => void
}) {
  const [toolbarRef, toolbarWidth] = useElementWidth()
  const isCompact =
    toolbarWidth !== null && toolbarWidth < PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH

  return (
    <div
      ref={toolbarRef}
      className="no-scrollbar flex h-10 shrink-0 items-center gap-1 overflow-x-auto border-b bg-card px-2"
    >
      <div className="flex min-w-0 shrink-0 items-center gap-1">
        <span className="px-1 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
          Page {currentPage} of {pageCount}
        </span>
        <ModeTabs mode={mode} onChange={onModeChange} />
      </div>
      <div className="ml-auto flex shrink-0 items-center gap-1">
        <ToolbarIconButton label="Zoom out" onClick={() => onZoom(1 / 1.2)}>
          <Minus />
        </ToolbarIconButton>
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {Math.round(scale * 100)}%
        </span>
        <ToolbarIconButton label="Zoom in" onClick={() => onZoom(1.2)}>
          <Plus />
        </ToolbarIconButton>
        <ToolbarIconButton label="Fit width" onClick={onFitWidth}>
          <Maximize />
        </ToolbarIconButton>
        <Separator orientation="vertical" className="mx-1 h-4" />
        {isCompact ? (
          <MarkdownActionsMenu text={text} fileName={fileName} />
        ) : (
          <MarkdownActionButtons text={text} fileName={fileName} />
        )}
      </div>
    </div>
  )
}

function ModeTabs({
  mode,
  onChange,
}: {
  mode: PageMarkdownViewMode
  onChange: (mode: PageMarkdownViewMode) => void
}) {
  return (
    <Tabs
      value={mode}
      onValueChange={(value) => onChange(value as PageMarkdownViewMode)}
    >
      <TabsList variant="underline" className="py-0">
        <TabsTrigger value="rendered" className="h-8 text-xs sm:text-xs">
          Rendered
        </TabsTrigger>
        <TabsTrigger value="text" className="h-8 text-xs sm:text-xs">
          Text
        </TabsTrigger>
      </TabsList>
    </Tabs>
  )
}

function ToolbarIconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

"use client"

import * as React from "react"
import { Check, Copy, Download, MoreHorizontal } from "lucide-react"

import { createTextDownloadAction } from "@/lib/viewer-download"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  useViewerDownloadTrigger,
  type ViewerDownloadErrorHandler,
} from "@/components/ui/viewer-download"

type CopyStatus = "idle" | "copied" | "failed"

function scheduleCopyStatusReset(
  timeoutRef: React.MutableRefObject<number | null>,
  setStatus: React.Dispatch<React.SetStateAction<CopyStatus>>
) {
  timeoutRef.current = window.setTimeout(() => {
    timeoutRef.current = null
    setStatus("idle")
  }, 1200)
}

function clearCopyStatusReset(
  timeoutRef: React.MutableRefObject<number | null>
) {
  if (timeoutRef.current === null) return
  window.clearTimeout(timeoutRef.current)
  timeoutRef.current = null
}

export function MarkdownActionButtons({
  text,
  fileName,
  onDownloadError,
}: {
  text: string
  fileName: string
  onDownloadError?: ViewerDownloadErrorHandler
}) {
  return (
    <>
      <CopyMarkdownButton text={text} />
      <DownloadMarkdownButton
        text={text}
        fileName={fileName}
        onDownloadError={onDownloadError}
      />
    </>
  )
}

export function MarkdownActionsMenu({
  text,
  fileName,
  onDownloadError,
}: {
  text: string
  fileName: string
  onDownloadError?: ViewerDownloadErrorHandler
}) {
  const copy = useCopyMarkdown(text)
  const download = useDownloadMarkdown(text, fileName, onDownloadError)

  return (
    <DropdownMenu modal={false}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon-sm"
          className="size-7"
          aria-label="More markdown actions"
          title="More markdown actions"
        >
          <MoreHorizontal />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuItem onClick={copy.write}>
          <Copy />
          {copy.status === "copied"
            ? "Copied"
            : copy.status === "failed"
              ? "Copy failed"
              : "Copy markdown"}
        </DropdownMenuItem>
        <DropdownMenuItem
          disabled={download.isPending}
          onClick={download.trigger}
        >
          <Download />
          Download markdown
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function CopyMarkdownButton({ text }: { text: string }) {
  const copy = useCopyMarkdown(text)

  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={copy.status === "failed" ? "Copy failed" : "Copy markdown"}
      title={copy.status === "failed" ? "Copy failed" : "Copy all markdown"}
      onClick={copy.write}
    >
      {copy.status === "copied" ? (
        <Check className="text-emerald-600" />
      ) : (
        <Copy className={copy.status === "failed" ? "text-destructive" : ""} />
      )}
    </Button>
  )
}

function DownloadMarkdownButton({
  text,
  fileName,
  onDownloadError,
}: {
  text: string
  fileName: string
  onDownloadError?: ViewerDownloadErrorHandler
}) {
  const download = useDownloadMarkdown(text, fileName, onDownloadError)

  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label="Download markdown"
      title="Download markdown"
      loading={download.isPending}
      onClick={download.trigger}
    >
      <Download />
    </Button>
  )
}

function useCopyMarkdown(text: string) {
  const [status, setStatus] = React.useState<CopyStatus>("idle")
  const timeoutRef = React.useRef<number | null>(null)
  const isMountedRef = React.useRef(true)
  const copyAttemptRef = React.useRef(0)

  React.useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      clearCopyStatusReset(timeoutRef)
    }
  }, [])

  const write = React.useCallback(() => {
    clearCopyStatusReset(timeoutRef)
    const copyAttempt = copyAttemptRef.current + 1
    copyAttemptRef.current = copyAttempt

    const isCurrentCopyAttempt = () =>
      isMountedRef.current && copyAttemptRef.current === copyAttempt

    try {
      const clipboard = navigator.clipboard
      const writeText = clipboard?.writeText
      if (typeof writeText !== "function") {
        setStatus("failed")
        scheduleCopyStatusReset(timeoutRef, setStatus)
        return
      }

      Promise.resolve(writeText.call(clipboard, text)).then(
        () => {
          if (!isCurrentCopyAttempt()) return
          setStatus("copied")
          scheduleCopyStatusReset(timeoutRef, setStatus)
        },
        () => {
          if (!isCurrentCopyAttempt()) return
          setStatus("failed")
          scheduleCopyStatusReset(timeoutRef, setStatus)
        }
      )
    } catch {
      setStatus("failed")
      scheduleCopyStatusReset(timeoutRef, setStatus)
    }
  }, [text])

  return { status, write }
}

function useDownloadMarkdown(
  text: string,
  fileName: string | undefined,
  onError: ViewerDownloadErrorHandler | undefined
) {
  const action = React.useMemo(
    () => downloadMarkdownAction(text, fileName),
    [fileName, text]
  )
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  })
  const trigger = React.useCallback(() => {
    triggerDownload(action)
  }, [action, triggerDownload])

  return {
    isPending: pendingActionId === action.id,
    trigger,
  }
}

export function normalizeMarkdownFileName(fileName?: string): string {
  const trimmed = fileName?.trim()
  if (!trimmed) return "document.md"
  if (/\.(?:md|markdown)$/i.test(trimmed)) return trimmed

  const slashIndex = Math.max(
    trimmed.lastIndexOf("/"),
    trimmed.lastIndexOf("\\")
  )
  const dotIndex = trimmed.lastIndexOf(".")
  if (dotIndex > slashIndex + 1) return `${trimmed.slice(0, dotIndex)}.md`

  return `${trimmed}.md`
}

export function downloadMarkdownAction(text: string, fileName?: string) {
  return createTextDownloadAction({
    id: "download-markdown",
    label: "Download markdown",
    text,
    fileName: normalizeMarkdownFileName(fileName),
    mimeType: "text/markdown;charset=utf-8",
    origin: "derived",
  })
}

"use client"

import * as React from "react"

import { Spinner } from "@/components/ui/spinner"
import { PageMarkdownContent } from "@/components/viewers/page-markdown/page-markdown-content"
import { useMarkdownPageMeasurement } from "@/components/viewers/page-markdown/page-markdown-hooks"
import {
  PAGE_MARKDOWN_PAGE_PADDING_X,
  PAGE_MARKDOWN_PAGE_PADDING_Y,
  PAGE_MARKDOWN_PAGE_WIDTH,
} from "@/components/viewers/page-markdown/page-markdown-model"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export const PageMarkdownPageFrame = React.memo(function PageMarkdownPageFrame({
  page,
  markdown,
  mode,
  scale,
}: {
  page: number
  markdown: string
  mode: PageMarkdownViewMode
  scale: number
}) {
  const [isNearViewport, setIsNearViewport] = React.useState(false)
  const { reservedHeight, measureRef } = useMarkdownPageMeasurement({
    markdown,
    mode,
    scale,
  })

  const pageRef = React.useCallback(
    (pageElement: HTMLDivElement | null) => {
      if (!pageElement) return

      const cleanupMeasurement = measureRef(pageElement)
      const root = pageElement.closest<HTMLElement>(
        '[data-slot="scroll-area-viewport"]'
      )
      if (typeof IntersectionObserver !== "function") {
        setIsNearViewport(true)
        return () => cleanupMeasurement?.()
      }

      const observer = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            setIsNearViewport(entry.isIntersecting)
          }
        },
        { root, rootMargin: "200% 0px" }
      )

      observer.observe(pageElement)
      return () => {
        observer.disconnect()
        cleanupMeasurement?.()
      }
    },
    [measureRef]
  )

  return (
    <div
      ref={pageRef}
      data-slot="page-markdown-page"
      data-page-number={page}
      className="relative w-full max-w-3xl bg-card shadow-sm ring-1 ring-border"
      style={{
        width: `${PAGE_MARKDOWN_PAGE_WIDTH * scale}px`,
        maxWidth: scale <= 1 ? "100%" : "none",
        paddingInline: `${PAGE_MARKDOWN_PAGE_PADDING_X * scale}px`,
        paddingBlock: `${PAGE_MARKDOWN_PAGE_PADDING_Y * scale}px`,
        ...(isNearViewport ? null : { height: reservedHeight }),
      }}
    >
      {isNearViewport ? (
        <PageMarkdownContent markdown={markdown} mode={mode} scale={scale} />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center">
          <Spinner className="size-4 text-muted-foreground" />
        </div>
      )}
    </div>
  )
})

