"use client"

import * as React from "react"

import {
  createPageMeasurementKey,
  estimateMarkdownPageHeight,
  initialPagePaneState,
  resolvePagePaneReport,
  type PagePane,
  type PendingPageScroll,
} from "@/components/viewers/page-markdown/page-markdown-model"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export function useMarkdownPageMeasurement({
  markdown,
  mode,
  scale,
}: {
  markdown: string
  mode: PageMarkdownViewMode
  scale: number
}) {
  const key = createPageMeasurementKey({ markdown, mode, scale })
  const [measurement, setMeasurement] = React.useState<{
    key: string
    height: number | null
  }>({ key, height: null })

  React.useEffect(() => {
    setMeasurement({ key, height: null })
  }, [key])

  const measureRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return

      if (typeof ResizeObserver !== "function") {
        if (element.offsetHeight > 0) {
          setMeasurement({ key, height: element.offsetHeight })
        }
        return
      }

      const observer = new ResizeObserver(() => {
        if (element.offsetHeight > 0) {
          setMeasurement({ key, height: element.offsetHeight })
        }
      })

      observer.observe(element)
      return () => observer.disconnect()
    },
    [key]
  )

  return {
    reservedHeight:
      measurement.key === key && measurement.height !== null
        ? measurement.height
        : estimateMarkdownPageHeight(markdown, scale),
    measureRef,
  }
}

export function usePagePaneSync({
  onMarkdownPageChange,
  pageCount,
  resetKey,
}: {
  onMarkdownPageChange?: (page: number) => void
  pageCount?: number
  resetKey?: string
}) {
  const [state, setState] = React.useState(initialPagePaneState)
  const stateRef = React.useRef(state)
  const pendingRef = React.useRef<PendingPageScroll | null>(null)
  const pageCountLimit = Math.max(1, pageCount ?? 1)

  React.useEffect(() => {
    const nextState = initialPagePaneState()
    stateRef.current = nextState
    pendingRef.current = null
    setState(nextState)
  }, [resetKey])

  React.useEffect(() => {
    const currentState = stateRef.current
    const nextPage = Math.min(currentState.page, pageCountLimit)
    const nextState =
      nextPage === currentState.page
        ? currentState
        : { ...currentState, page: nextPage, version: currentState.version + 1 }
    const currentPending = pendingRef.current

    stateRef.current = nextState
    pendingRef.current =
      currentPending && currentPending.page <= pageCountLimit
        ? currentPending
        : null
    setState(nextState)
  }, [pageCountLimit])

  React.useEffect(() => {
    stateRef.current = state
  }, [state])

  const reportPage = React.useCallback(
    (pane: PagePane, page: number) => {
      const transition = resolvePagePaneReport({
        state: stateRef.current,
        pending: pendingRef.current,
        pane,
        page,
      })

      stateRef.current = transition.state
      pendingRef.current = transition.pending
      setState(transition.state)

      if (transition.state.pane === "markdown") {
        onMarkdownPageChange?.(transition.state.page)
      }

      return transition.scrollTarget
    },
    [onMarkdownPageChange]
  )

  return {
    currentPage: state.page,
    reportMarkdownPage: React.useCallback(
      (page: number) => reportPage("markdown", page),
      [reportPage]
    ),
    reportDocumentPage: React.useCallback(
      (page: number) => reportPage("document", page),
      [reportPage]
    ),
  }
}

export const PAGE_MARKDOWN_PAGE_WIDTH = 768
export const PAGE_MARKDOWN_PAGE_PADDING_X = 36
export const PAGE_MARKDOWN_PAGE_PADDING_Y = 28
export const PAGE_MARKDOWN_SCALE_MIN = 0.35
export const PAGE_MARKDOWN_SCALE_MAX = 3
export const PAGE_MARKDOWN_FIT_SCALE_MAX = 1.5
export const PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING = 32
export const PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH = 460

export type PagePane = "markdown" | "document"

export interface PagePaneState {
  page: number
  pane: PagePane
  version: number
}

export interface PendingPageScroll {
  pane: PagePane
  page: number
  version: number
}

export interface PagePaneTransition {
  state: PagePaneState
  pending: PendingPageScroll | null
  scrollTarget: PendingPageScroll | null
  confirmed: boolean
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

export function clampPageScale(scale: number): number {
  if (!Number.isFinite(scale)) return 1
  return clamp(scale, PAGE_MARKDOWN_SCALE_MIN, PAGE_MARKDOWN_SCALE_MAX)
}

export function fitPageScale(containerWidth: number | null): number {
  if (!containerWidth || !Number.isFinite(containerWidth)) return 1
  return clamp(
    (containerWidth - PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING) /
      PAGE_MARKDOWN_PAGE_WIDTH,
    PAGE_MARKDOWN_SCALE_MIN,
    PAGE_MARKDOWN_FIT_SCALE_MAX
  )
}

export function zoomPageScale(scale: number, factor: number): number {
  return clampPageScale(scale * factor)
}

export function estimateMarkdownPageHeight(
  markdown: string,
  scale: number
): number {
  const safeScale = clampPageScale(scale)
  const lineCount = markdown.split("\n").length
  return Math.min(
    1800 * safeScale,
    Math.max(180 * safeScale, lineCount * 26 * safeScale + 80 * safeScale)
  )
}

export function joinMarkdownPages(pages: string[]): string {
  return pages.join("\n\n")
}

export function createPageMeasurementKey({
  markdown,
  mode,
  scale,
}: {
  markdown: string
  mode: string
  scale: number
}): string {
  return `${mode}:${scale.toFixed(3)}:${markdown.length}:${hashMarkdown(markdown)}`
}

function hashMarkdown(markdown: string): string {
  let hash = 2166136261
  for (let index = 0; index < markdown.length; index += 1) {
    hash ^= markdown.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return (hash >>> 0).toString(36)
}

export function initialPagePaneState(): PagePaneState {
  return { page: 1, pane: "markdown", version: 0 }
}

export function resolvePagePaneReport({
  state,
  pending,
  pane,
  page,
}: {
  state: PagePaneState
  pending: PendingPageScroll | null
  pane: PagePane
  page: number
}): PagePaneTransition {
  const nextPage = Math.max(1, Number.isFinite(page) ? Math.floor(page) : 1)

  if (pending?.pane === pane && pending.page === nextPage) {
    return {
      state: { page: nextPage, pane, version: state.version + 1 },
      pending: null,
      scrollTarget: null,
      confirmed: true,
    }
  }

  if (pending?.pane === pane) {
    return {
      state,
      pending,
      scrollTarget: null,
      confirmed: false,
    }
  }

  if (!pending && state.page === nextPage && state.pane === pane) {
    return {
      state,
      pending: null,
      scrollTarget: null,
      confirmed: false,
    }
  }

  if (!pending && state.page === nextPage) {
    return {
      state: { page: nextPage, pane, version: state.version + 1 },
      pending: null,
      scrollTarget: null,
      confirmed: false,
    }
  }

  const targetPane: PagePane = pane === "markdown" ? "document" : "markdown"
  const nextState = { page: nextPage, pane, version: state.version + 1 }
  const nextPending = {
    pane: targetPane,
    page: nextPage,
    version: nextState.version,
  }

  return {
    state: nextState,
    pending: nextPending,
    scrollTarget: nextPending,
    confirmed: false,
  }
}

export const PAGE_MARKDOWN_VISIBLE_PAGE_MARKER_RATIO = 0.2

export function getVisiblePageFromViewport(
  viewport: HTMLElement,
  markerRatio = PAGE_MARKDOWN_VISIBLE_PAGE_MARKER_RATIO
): number {
  const viewportRect = viewport.getBoundingClientRect()
  const pageMarker = viewportRect.top + viewportRect.height * markerRatio
  const pageElements =
    viewport.querySelectorAll<HTMLElement>("[data-page-number]")
  let visiblePage = 1

  for (const pageElement of pageElements) {
    if (pageElement.getBoundingClientRect().top > pageMarker) break

    const page = Number(pageElement.dataset.pageNumber)
    if (Number.isFinite(page) && page > 0) {
      visiblePage = page
    }
  }

  return visiblePage
}

export function scrollPageIntoView(
  root: HTMLElement | null,
  page: number
): void {
  const target = root?.querySelector<HTMLElement>(`[data-page-number="${page}"]`)
  if (typeof target?.scrollIntoView !== "function") return

  target.scrollIntoView({ behavior: "smooth", block: "start" })
}

"use client"

import * as React from "react"

export function useElementWidth<T extends HTMLElement = HTMLDivElement>(): [
  React.RefCallback<T>,
  number | null,
] {
  const cleanupRef = React.useRef<(() => void) | null>(null)
  const [width, setWidth] = React.useState<number | null>(null)

  const ref = React.useCallback((element: T | null) => {
    cleanupRef.current?.()
    cleanupRef.current = null

    if (!element) return

    setWidth(element.clientWidth)
    if (typeof ResizeObserver !== "function") return

    let frame = 0
    let nextWidth = element.clientWidth
    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        nextWidth = (entry.target as HTMLElement).clientWidth
      }
      if (frame) return
      if (typeof requestAnimationFrame !== "function") {
        setWidth(nextWidth)
        return
      }
      frame = requestAnimationFrame(() => {
        frame = 0
        setWidth(nextWidth)
      })
    })

    observer.observe(element)
    cleanupRef.current = () => {
      if (frame && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame)
      }
      observer.disconnect()
    }
  }, [])

  React.useEffect(() => () => cleanupRef.current?.(), [])

  return [ref, width]
}

